def derivative(f, x, h=1e-6):
    return (f(x + h) - f(x - h)) / (2 * h)       # symmetric difference quotient

f = lambda x: x ** 3
for x in (1, 2, 3):
    print(x, round(derivative(f, x), 4), 3 * x ** 2)   # numerical slope against the exact 3x^2

