checks = {
    "x^5":       (lambda x: x ** 5,        lambda x: 5 * x ** 4),
    "sin(x)e^x": (lambda x: math.sin(x) * math.exp(x), lambda x: (math.cos(x) + math.sin(x)) * math.exp(x)),
    "ln(x^2+1)": (lambda x: math.log(x * x + 1),       lambda x: 2 * x / (x * x + 1)),
}
