import math

class Dual:                                   # a value together with its derivative
    def __init__(self, val, der=0.0):
        self.val, self.der = val, der
    def __add__(self, o):
        o = o if isinstance(o, Dual) else Dual(o)
        return Dual(self.val + o.val, self.der + o.der)
    __radd__ = __add__
    def __mul__(self, o):
        o = o if isinstance(o, Dual) else Dual(o)
        return Dual(self.val * o.val, self.der * o.val + self.val * o.der)
    __rmul__ = __mul__

def sin(x):
    return Dual(math.sin(x.val), math.cos(x.val) * x.der)

x = Dual(2.0, 1.0)                            # seed: dx/dx = 1
y = x * x * sin(x) + 3 * x                    # f(x) = x^2 sin x + 3x
print(y.val, y.der)                           # f(2) and f'(2), computed together
print(2 * 2 * math.sin(2) + 4 * math.cos(2) + 3)      # f'(2) by the rules: 2x sin x + x^2 cos x + 3

def newton(f, df, x, steps=6):
    for i in range(steps):
        x = x - f(x) / df(x)
        print(i + 1, x)
    return x

newton(lambda x: x * x - 2, lambda x: 2 * x, 1.0)
